 rv=validate_runtime_adapter_activation_token_review_request(review_request).valid; dv=validate_runtime_adapter_activation_token_review(review).valid; pv=validate_runtime_adapter_activation_token_preparation(preparation).valid; ev=validate_runtime_adapter_activation_token_eligibility(eligibility).valid; pov=validate_runtime_adapter_activation_token_authorization_policy(policy).valid
