 return stable_artifact({'schema':SCHEMA,'token_authorization_policy_id':policy.get(POLICY_ID),'token_authorization_policy_fingerprint':policy.get('fingerprint'),'token_review_request_id':review_request.get('token_review_request_id'),'token_review_request_fingerprint':review_request.get('fingerprint'),'token_review_id':review.get('token_review_id'),'token_review_fingerprint':review.get('fingerprint'),'token_preparation_id':preparation.get('token_preparation_id'),'token_preparation_fingerprint':preparation.get('fingerprint'),'token_eligibility_id':eligibility.get('token_eligibility_id'),'token_eligibility_fingerprint':eligibility.get('fingerprint'),'activation_authorization_handoff_id':review.get('activation_authorization_handoff_id'),'activation_authorization_id':review.get('activation_authorization_id'),'adapter_id':review.get('adapter_id'),'adapter_version':review.get('adapter_version'),'authorized_token_scope':review.get('requested_token_scope') if ok else {},'max_uses':review.get('max_uses'),'token_constraints':review.get('token_constraints'),'authority_reference':review.get('authority_reference'),'authority_constraints':review.get('authority_constraints'),'authorization_status':'authorized' if ok else ('invalid' if not (rv and dv and pv and ev and pov) else 'not_authorized'),'reason_codes':normalize_reasons([] if ok else ['token_authorization_not_permitted']),'passive_only':True,'token_issuance_authorized':ok,'token_issued':False,'token_consumed':False,'token_material_present':False,'adapter_loaded':False,'adapter_activated':False,'adapter_invoked':False,'runtime_invoked':False,'authority_consumed':False,'mutation_performed':False},ID,PREFIX)
