 r=validate_artifact(v,schema=SCHEMA,id_key=ID,prefix=PREFIX,fields=FIELDS,status_key='authorization_status',statuses={'authorized','not_authorized','invalid'}); e=list(r.errors)
 if isinstance(v,Mapping) and (v.get('token_issuance_authorized') is not (v.get('authorization_status')=='authorized') or not passive_invariants_valid(v) or v.get('token_issued') is not False or v.get('token_consumed') is not False): e.append('passive_invariant_violation')
 return ValidationResult(not e,tuple(dict.fromkeys(e)))
